import java.util.Scanner;

class Ushwa
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a four-digit number: ");
        int n = sc.nextInt();
        if (n < 1000 || n > 9999)
        {
            System.out.println("Error: the number does not have exactly 4 digits");
            return;
        }
        int first = n / 1000;      // first digit
        int last = n % 10;         // last digit
        int t = n, sum = 0;
        while (t > 0)
        {
            sum = sum + t % 10;    // sum of all digits
            t = t / 10;
        }
        if (sum == 2 * (first + last))
            System.out.println(n + " is a USHWA number");
        else
            System.out.println(n + " is not a USHWA number");
    }
}

Trace: n = 1234 -> first + last = 1 + 4 = 5, sum of digits = 10 = 2 x 5 -> "1234 is a USHWA number".
n = 354 -> fails the 4-digit check -> error message.

